    FB("Sinds de verhuizing heb ik last van ___.", ["slapeloosheid"], "Insónia.", ["v-slapeloosheid"], choices=["slapeloosheid","slaap","dutje"], tr="Desde a mudança sofro de insónias."),
    LI("Ik word elke nacht om vier uur wakker en kan dan niet meer slapen.", ["Ik word elke nacht om vier uur wakker en kan dan niet meer slapen"], "Acordo todas as noites às quatro e depois já não consigo dormir.", "wakker worden.", ["v-doorslapen"]),
    WO("Durmo mal.", ["Ik","slaap","slecht"], "Ordem.", ["v-slaap"]),
