L(14, "Esgotamento", "Overspannen of een burn-out.",
  ["Falar de stress prolongado com sensibilidade"],
  vocab=[V("v-overspannen","overspannen","esgotado (de stress)","adjective"), V("v-re-integratie","re-integratie","reintegração (no trabalho)","noun","de"),
         V("v-bedrijfsarts","bedrijfsarts","médico do trabalho","noun","de"), V("v-signalen","signalen","sinais","noun","de")],
  ex=[("Hij is overspannen en zit thuis.","Ele está esgotado e está em casa."),("Na drie maanden begon haar re-integratie.","Ao fim de três meses começou a reintegração dela."),("De bedrijfsarts geeft advies.","O médico do trabalho dá conselhos."),("Let op de signalen van stress.","Presta atenção aos sinais de stress.")],
  review=["v-burn-out","v-werkdruk","v-grens"],
  cefr=C, exs=[
    MA([("overspannen","esgotado"),("re-integratie","reintegração"),("bedrijfsarts","médico do trabalho"),("signalen","sinais")], "Stress.", ["v-overspannen","v-re-integratie","v-bedrijfsarts","v-signalen"]),
    CO("text","Te veel stress", "Bij langdurige stress kunnen mensen overspannen raken of een burn-out krijgen. Signalen zijn bijvoorbeeld slecht slapen, snel geïrriteerd zijn en moeite met concentreren. Wie zich ziek meldt, krijgt in Nederland contact met de bedrijfsarts. Die helpt bij een plan om stap voor stap weer aan het werk te gaan: de re-integratie. Het is belangrijk om op tijd je grenzen aan te geven.",
       [("Que sinais se referem?", ["*Dormir mal, irritabilidade, falta de concentração","Fome","Febre alta"]),("Quem ajuda no plano de regresso?", ["*O médico do trabalho","O chefe sozinho","Ninguém"]),("O que é importante?", ["*Indicar os limites a tempo","Trabalhar mais","Não dizer nada"])],
       "Informação geral.", ["v-overspannen","v-bedrijfsarts","v-re-integratie","v-signalen"]),
    TR("pt-nl","Ele está esgotado.", ["Hij is overspannen"], "overspannen.", ["v-overspannen"]),
    TR("pt-nl","Presta atenção aos sinais.", ["Let op de signalen","Let goed op de signalen"], "letten op.", ["v-signalen"]),
    DL([("Collega","Het gaat niet goed met me. Ik slaap slecht en ik kan me niet concentreren.","Não estou bem. Durmo mal e não me consigo concentrar."),("Jij","","")], ["*Dat klinkt zwaar. Heb je het al met je leidinggevende of de huisarts besproken?","Werk gewoon harder.|Insensível.","Ik ook niet, dag.|Pouco empático."], "Reagir com empatia.", ["v-signalen"]),
    FE(["Ze","heeft","overspannen","geraakt."], 1, "is", "raken usa zijn.", ["v-overspannen"]),
    FB("De ___ maakt samen met jou een plan.", ["bedrijfsarts"], "Médico do trabalho.", ["v-bedrijfsarts"], choices=["bedrijfsarts","psycholoog","tandarts"], tr="O médico do trabalho faz um plano contigo."),
    AR("bedrijfsarts","o médico do trabalho","de", "De arts.", ["v-bedrijfsarts"]),
    LI("Geef op tijd je grenzen aan.", ["Geef op tijd je grenzen aan"], "Indica os teus limites a tempo.", "aangeven.", ["v-grens"]),
    WO("Ele está em casa com esgotamento.", ["Hij","zit","overspannen","thuis"], "Ordem.", ["v-overspannen"]),
  ], diff=4, mins=7)

